@using sv_915469a1f486482081f3da2edaf39409.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h3>Notifications</h3>
    <p class="section-description">Control how and when you receive notifications.</p>

    @if (_loading)
    {
        <div class="loading">Loading preferences...</div>
    }
    else
    {
        <div class="toggles-group">
            <div class="toggle-item">
                <div class="toggle-info">
                    <span class="toggle-label">Email Notifications</span>
                    <span class="toggle-desc">Receive notifications via email</span>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="slider"></span>
                </label>
            </div>

            <div class="toggle-item">
                <div class="toggle-info">
                    <span class="toggle-label">Push Notifications</span>
                    <span class="toggle-desc">Receive push notifications in your browser</span>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="slider"></span>
                </label>
            </div>

            <div class="toggle-item">
                <div class="toggle-info">
                    <span class="toggle-label">Weekly Digest</span>
                    <span class="toggle-desc">Get a weekly summary of activity</span>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        <div class="channels-section">
            <h4>Muted Channels</h4>
            <p class="section-description">Select channels to mute notifications from.</p>
            <div class="channels-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">✓ Notification preferences saved!</div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();

    private readonly string[] _allChannels = ["general", "announcements", "engineering", "design", "marketing", "support"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        _saving = false;
        _showSuccess = true;

        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

