<section class="settings-section">
    <h3>Appearance</h3>
    <p class="section-description">Customize the look and feel of your application.</p>

    @if (_loading)
    {
        <div class="loading">Loading appearance settings...</div>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="option-group">
                <label class="option-label">Theme</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Light" @onchange="@(() => _theme = "Light")" checked="@(_theme == "Light")" />
                        <span>☀️ Light</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Dark" @onchange="@(() => _theme = "Dark")" checked="@(_theme == "Dark")" />
                        <span>🌙 Dark</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="System" @onchange="@(() => _theme = "System")" checked="@(_theme == "System")" />
                        <span>💻 System</span>
                    </label>
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="option-group">
                <label class="option-label">Font Size</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Small" @onchange="@(() => _fontSize = "Small")" checked="@(_fontSize == "Small")" />
                        <span class="font-small">Small</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Medium" @onchange="@(() => _fontSize = "Medium")" checked="@(_fontSize == "Medium")" />
                        <span class="font-medium">Medium</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Large" @onchange="@(() => _fontSize = "Large")" checked="@(_fontSize == "Large")" />
                        <span class="font-large">Large</span>
                    </label>
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="option-group">
                <label class="option-label" for="language">Language</label>
                <select id="language" @bind="_language">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <!-- Compact Mode Toggle -->
            <div class="option-group">
                <div class="toggle-item">
                    <div class="toggle-info">
                        <span class="toggle-label">Compact Mode</span>
                        <span class="toggle-desc">Reduce spacing and padding for a denser layout</span>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_compactMode" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h5>Live Preview</h5>
            <div class="preview-content">
                <p class="preview-heading">Sample Heading</p>
                <p class="preview-text">This is how your content will look with the selected appearance settings. The theme, font size, and compact mode are reflected here.</p>
