{"file_text": ".settings-section h3 {
    margin-bottom: 0.25rem;
    font-size: 1.5rem;
    font-weight: 600;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.5rem;
}

.loading {
    padding: 2rem;
    text-align: center;
    color: #6c757d;
}

.appearance-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.option-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.option-label {
    font-weight: 500;
    font-size: 0.95rem;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    cursor: pointer;
    transition: border-color 0.15s, background 0.15s;
    font-size: 0.9rem;
}

.radio-item:hover {
    background: #f8f9fa;
}

.radio-item:has(input:checked) {
    border-color: #0d6efd;
    background: #e7f1ff;
}

.radio-item input[type="radio"] {
    accent-color: #0d6efd;
}

.font-small { font-size: 0.8rem; }
.font-medium { font-size: 0.95rem; }
.font-large { font-size: 1.1rem; }

.option-group select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    max-width: 250px;
}

.option-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.1);
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 1.25rem;
    border: 1px solid #dee2e6;
    border-radius: 8px;
}

.toggle-info {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.toggle-label {
    font-weight: 500;
    font-size: 0.95rem;
}

.toggle-desc {
    font-size: 0.8rem;
    color: #6c757d;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 24px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

/* Live Preview */
.preview-area {
    margin-top: 2rem;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
}

.preview-area h5 {
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-bottom: 1px solid #dee2e6;
    font-size: 0.85rem;
    font-weight: 600;
    color: #6c757d;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin: 0;
}

.preview-content {
    padding: 1.5rem;
    transition: all 0.2s;
}

.preview-heading {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    color: #495057;
    margin-bottom: 1rem;
    line-height: 1.5;
}

.preview-buttons {
    display: flex;
    gap: 0.5rem;
}

.preview-btn {
    padding: 0.4rem 1rem;
    border-radius: 6px;
    font-size: 0.85rem;
    font-weight: 500;
}

.preview-btn.primary {
    background: #0d6efd;
    color: white;
}

.preview-btn.secondary {
    background: #e9ecef;
    color: #495057;
}

/* Theme previews */
.preview-area.theme-dark .preview-content {
    background: #1a1a2e;
    color: #e0e0e0;
}

.preview-area.theme-dark .preview-text {
    color: #a0a0b0;
}

.preview-area.theme-dark .preview-btn.secondary {
    background: #2d2d44;
    color: #c0c0d0;
}

.preview-area.theme-light .preview-content {
    background: #ffffff;
    color: #212529;
}

.preview-area.theme-system .preview-content {
    background: #f0f4f8;
    color: #212529;
}

/* Font size previews */
.preview-area.size-small .preview-content {
    font-size: 0.8rem;
}

.preview-area.size-small .preview-heading {
    font-size: 1rem;
}

.preview-area.size-medium .preview-content {
    font-size: 0.95rem;
}

.preview-area.size-medium .preview-heading {
    font-size: 1.15rem;
}

.preview-area.size-large .preview-content {
    font-size: 1.1rem;
}

.preview-area.size-large .preview-heading {
    font-size: 1.35rem;
}

/* Compact mode preview */
.preview-area.compact .preview-content {
    padding: 0.75rem;
}

.preview-area.compact .preview-heading {
    margin-bottom: 0.25rem;
}

.preview-area.compact .preview-text {
    margin-bottom: 0.5rem;
    line-height: 1.3;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.5rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background 0.15s, opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: slideIn 0.2s ease;
}

.toast.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-8px); }
    to { opacity: 1; transform: translateY(0); }
}
